INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 16, 'theory', 'Quiz: LVM');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 16, 0, 'A group has a 4 MiB extent. What size will the volume have after lvcreate -L 10M?', '["8 MiB", "10 MiB", "12 MiB", "The command fails: 10 is not a multiple of 4"]', 2, 'A volume''s size is always a multiple of the extent, and a requested size is rounded up: 10 MiB becomes three extents, that is 12 MiB. The command prints a message about it.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 16, 1, 'A group has 101 free extents. How many extents will lvcreate -l 50%FREE take?', '["50", "51", "49", "101"]', 0, 'When a volume is created the percentage is computed in integers and rounded down: 50.5 gives 50. In lvextend the percentage is rounded up, and the same share would give 51.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 16, 2, 'A classic snapshot''s area is 100% full. What happens to the snapshot?', '["It grows by itself while the group has room", "It turns into a thin snapshot", "Writes to the origin block until it is extended", "It becomes invalid (letter I in Attr) and reads give errors"]', 3, 'Automatic extension works only if the threshold is set and dmeventd runs, and a full snapshot is disabled by the kernel and returns errors. The origin keeps working.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 16, 3, 'A thin pool''s data is 100% full. What does the pool do by default?', '["It deletes the oldest thin volume", "It queues writes for up to 60 seconds waiting for an extension, then returns errors", "It compacts the metadata and keeps writing", "It silently overwrites the oldest blocks"]', 1, 'That is the default whenfull behaviour. So the pool is extended early, and the autoextend threshold is set below 100.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 16, 4, 'How do you correctly shrink a volume holding ext4?', '["Run lvreduce first, then resize2fs", "Shrink XFS with xfs_growfs", "Shrink the filesystem first (ext4, unmounted), then the volume; lvreduce -r does both steps", "Just run lvreduce: LVM moves the data itself"]', 2, 'Cutting the extents before the filesystem loses the data in them. xfs_growfs only expands, and XFS cannot be shrunk at all.');
